function writer_csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}function writer_form_context(int$p,string$t,string$a):string{global$subtab;return writer_csrf_field().'<input type="hidden" name="plot_id" value="'.$p.'"><input type="hidden" name="tab" value="'.e($t).'">'.($subtab!==''?'<input type="hidden" name="subtab" value="'.e($subtab).'">':'').'<input type="hidden" name="action" value="'.e($a).'">';}
function writer_time_parts(int $seconds):array{foreach(['days'=>86400,'hours'=>3600,'minutes'=>60]as$unit=>$size)if($seconds>0&&$seconds%$size===0)return[$seconds/$size,$unit];return[$seconds,'seconds'];}
function writer_percent_text(float $percent):string{return rtrim(rtrim(number_format($percent,1),'0'),'.');}
function writer_event_percent(array $ev,array $plot):float{if(isset($ev['trigger_percent'])&&$ev['trigger_percent']!==null)return(float)$ev['trigger_percent'];$d=max(1,(int)($plot['timeline_duration_seconds']??300));return round((int)($ev['event_second']??0)*100/$d,1);}
function writer_hint(string $text):string{return'<span class="field-hint">'.e($text).'</span>';}
function writer_dependency_list(array$items):string{if(!$items)return'<div class="dependency-list dependency-empty"><b>Used by</b><span>No linked records.</span></div>';$html='<div class="dependency-list"><b>Used by</b><ul>';foreach($items as$item)$html.='<li>'.e($item).'</li>';return$html.'</ul></div>';}
function writer_usage_alert(array$items):string{return$items?' data-usage-alert="'.e("Deactivating this item also removes it from active story paths. Linked records:\n• ".implode("\n• ",$items)."\n\nContinue?").'"':'';}
function writer_stable_code_field(string$label,string$name,string$value,array$usage=[],string$hint='',bool$required=true):string{if($name==='story_code'&&isset($usage['STORY'])&&count($usage)===1){global$plotId;$usage=StoryAuthoringService::storyCodeUsage((int)$plotId);}$locked=(bool)$usage;$types=['code'=>'story','location_code'=>'location','role_code'=>'character','event_code'=>'event','option_code'=>'option','opportunity_code'=>'opportunity','target_code'=>'value','section_code'=>'ending'];$type='story';foreach($types as$key=>$candidate)if($name===$key||str_ends_with($name,'['.$key.']')){$type=$candidate;break;}$html='<label class="field stable-code-field identifier-'.e($type).'">'.'<span class="stable-code-label">'.e($label).'</span><input name="'.e($name).'" value="'.e($value).'"'.($required?' required':'').($locked?' disabled':'').'>';if($locked)$html.='<input type="hidden" name="'.e($name).'" value="'.e($value).'">';if($locked){$parts=[];foreach($usage as$keyword=>$count)$parts[]=e($keyword).' '.(int)$count;$html.='<span class="code-lock">Locked · '.implode(' · ',$parts).'</span>';}
elseif($hint!=='')$html.=writer_hint($hint);return$html.'</label>';}
function writer_set_value_field(?string$value):string{return'<label class="field set-field"><span data-set-value-label>Set To</span><select name="set_value" data-set-value-select data-current="'.e((string)$value).'"></select><input name="set_value" value="'.e((string)$value).'" data-set-value-text disabled>'.writer_hint('Preset values use an approved dropdown. Free Text values accept a short unrestricted state.').'</label>';}
function writer_operator_field(string$current,string$name='operator',bool$allowNone=false):string{$definitions=['EQ'=>'Equals','NEQ'=>'Does not equal','IN'=>'Matches one value in a comma-separated list','NOT_IN'=>'Matches none of the values in a comma-separated list','EXISTS'=>'Has any stored value; comparison value is ignored','NOT_EXISTS'=>'Has no stored value; comparison value is ignored','LT'=>'Is less than (Numerical only)','LTE'=>'Is less than or equal to (Numerical only)','GT'=>'Is greater than (Numerical only)','GTE'=>'Is greater than or equal to (Numerical only)'];$html='<label class="field operator-field">Operator<select name="'.e($name).'" data-operator-select>';if($allowNone)$html.='<option value="" data-meaning="No condition is applied.">None</option>';foreach($definitions as$code=>$meaning)$html.='<option value="'.e($code).'" data-meaning="'.e($meaning).'"'.($current===$code?' selected':'').'>'.e($code).'</option>';$html.='</select><span class="field-hint" data-operator-help></span></label>';return$html;}
function writer_condition_value_field(?string$value,string$name='compare_value'):string{$phases=['EXPOSITION'=>'Exposition','INCITING_INCIDENT'=>'Inciting Incident','RISING_ACTION'=>'Rising Action','CLIMAX'=>'Climax','RESOLUTION'=>'Resolution'];$phaseOptions='';$phaseToggles='';foreach($phases as$code=>$label){$phaseOptions.='<option value="'.e($code).'">'.e($label).'</option>';$phaseToggles.='<button type="button" data-phase-value="'.e($code).'" aria-pressed="false">'.e($label).'</button>';}$escapedName=e($name);return'<div class="field condition-value-field"><span>Value</span><select name="'.$escapedName.'" data-condition-phase-select data-current="'.e((string)$value).'">'.$phaseOptions.'</select><span class="value-toggle-grid" data-condition-phase-toggles>'.$phaseToggles.'</span><input type="hidden" name="'.$escapedName.'" data-condition-phase-hidden disabled><select name="'.$escapedName.'" data-condition-value-select data-current="'.e((string)$value).'"></select><span class="value-toggle-grid" data-condition-preset-toggles></span><input type="hidden" name="'.$escapedName.'" data-condition-preset-hidden disabled><input name="'.$escapedName.'" value="'.e((string)$value).'" data-condition-value-input>'.writer_hint('Phase and Preset Values use approved choices. For IN or NOT_IN, click each value to turn it on or off. EXISTS and NOT_EXISTS do not need a value.').'</div>';}
function writer_archetype_field(string$value):string{$options=StoryAuthoringService::ARCHETYPES;if($value!==''&&!in_array($value,$options,true))array_unshift($options,$value);$html='<label class="field">Archetype<select name="archetype">';foreach($options as$option)$html.='<option value="'.e($option).'"'.($value===$option?' selected':'').'>'.e($option).'</option>';return$html.'</select></label>';}
function writer_target_options(array $definitions,string $current):string{$html='<option value="">Choose a managed story value</option>';$found=false;foreach($definitions as$d){$selected=$current===$d['target_code'];if($selected)$found=true;$html.='<option value="'.e($d['target_code']).'" data-scope="'.e($d['effect_scope']).'" data-value-type="'.e($d['value_type']).'" data-values="'.e((string)$d['allowed_values_text']).'"'.($selected?' selected':'').'>'.e($d['label_text'].' · '.$d['target_code']).'</option>';}if($current!==''&&!$found)$html.='<option value="'.e($current).'" data-scope="LEGACY" selected>'.e($current.' · existing value').'</option>';return$html;}
function writer_definition_picker(array$definitions,array$usage=[]):string{$html='<label class="field wide">Edit Existing Story Value<select name="plot_state_definition_id" data-definition-picker><option value="0">Create a new story value</option>';foreach($definitions as$d){$parts=[];foreach(($usage[(int)$d['plot_state_definition_id']]??[])as$keyword=>$count)$parts[]=$keyword.' '.$count;$html.='<option value="'.(int)$d['plot_state_definition_id'].'" data-scope="'.e($d['effect_scope']).'" data-type="'.e($d['value_type']).'" data-label="'.e($d['label_text']).'" data-code="'.e($d['target_code']).'" data-default="'.e((string)$d['default_numeric_value']).'" data-default-text="'.e((string)($d['default_text_value']??'')).'" data-values="'.e((string)$d['allowed_values_text']).'" data-description="'.e((string)$d['description']).'" data-sort="'.(int)$d['sort_order'].'" data-usage="'.e(implode(' · ',$parts)).'">'.e($d['label_text'].' · '.$d['target_code']).'</option>';}$html.='</select>'.writer_hint('Choose a value to load it here, or leave this on Create New.').'</label><input type="hidden" name="sort_order" value="100">';return$html;}
