"></label><label class="field">Duration<select name="timeline_duration_seconds"><?php foreach(StoryAuthoringService::durationChoices($isAdmin,(int)($plot['timeline_duration_seconds']??300))as$durationSeconds=>$durationLabel):?><option value="<?=$durationSeconds?>" <?=$durationSeconds===(int)($plot['timeline_duration_seconds']??300)?'selected':''?>><?=e($durationLabel)?></option><?php endforeach;?></select><?=writer_hint('How long a game of this story runs. Events are placed by percentage of this duration, so changing it stretches or compresses the whole timeline proportionally. Admins also see 5, 10 and 15 minute durations for testing.')?></label><div class="field wide"><span>Host Durations</span><?php $hostDurationOptions=StoryAuthoringService::hostDurationOptions();$allowedHostDurations=StoryAuthoringService::allowedHostDurations((int)($plot['plot_id']??0));$ownDuration=(int)($plot['timeline_duration_seconds']??300);?><div class="duration-toggles" id="duration-toggles"><?php foreach($hostDurationOptions as$hdSeconds=>$hdLabel):$isOwn=$hdSeconds===$ownDuration;?><label class="duration-toggle<?=$isOwn?' locked':''?>"><input type="checkbox" name="allowed_host_durations[]" value="<?=$hdSeconds?>" data-label="<?=e($hdLabel)?>" <?=in_array($hdSeconds,$allowedHostDurations,true)?'checked':''?><?=$isOwn?' disabled':''?>><span><?=e($hdLabel)?><?=$isOwn?' · Story Duration':''?></span></label><?php endforeach;?></div><input type="hidden" name="allowed_host_durations_present" value="1"><?=writer_hint('Choose every game length hosts may offer for this story. Your story Duration above is always included. Typically, longer games need more events to keep the story moving. We recommend at least 6 events for games up to 30 minutes, 8 for 1 hour, 12 for 2 hours, 15 for 3 hours, and 16 or more for multi-day games, spread so that something lands every few hours of play.')?><span class="duration-gap-hint" id="duration-gap-hint"></span></div><?php $gapPercents=[];foreach(($w['events']??[])as$gapEvent)if((int)($gapEvent['active']??1)===1)$gapPercents[]=writer_event_percent($gapEvent,$plot);sort($gapPercents);$longestGap=0.0;$prevGap=0.0;foreach($gapPercents as$gapPct){$longestGap=max($longestGap,$gapPct-$prevGap);$prevGap=$gapPct;}?><script>(function(){var box=document.getElementById('duration-toggles'),hint=document.getElementById('duration-gap-hint');if(!box||!hint)return;var count=<?=count($gapPercents)?>,longest=<?=json_encode(round($longestGap,1))?>,rec={180:3,300:4,900:5,1800:6,3600:8,5400:10,7200:12,9000:14,10800:15,259200:16,432000:18,604800:20};function fmtGap(sec){if(sec>=86400)return (Math.round(sec/8640)/10)+' days';if(sec>=3600)return (Math.round(sec/360)/10)+' hours';if(sec>=90)return Math.round(sec/60)+' minutes';return Math.round(sec)+' seconds';}function update(){var chosen=[...box.querySelectorAll('input:checked')];if(!chosen.length){hint.textContent='';return;}var top=chosen[chosen.length-1];var d=parseInt(top.value,10);var gap=longest/100*d;var msg='This story has '+count+' events. At '+top.dataset.label+', the longest quiet stretch between events is about '+fmtGap(gap)+'.';var r=rec[d]||0;if(r&&count<r)msg+=' We recommend at least '+r+' events for a game that long.';else if(r)msg+=' That is enough events to keep a game that long moving.';hint.textContent=msg;}box.addEventListener('change',update);update();})();</script><label class="field">Public Standings Stat<select name="standings_stat_code"><option value="">None — no standings shown</option><?php foreach($w['state_definitions']as$definition):if((string)$definition['effect_scope']!=='STAT'||(int)($definition['active']??1)!==1)continue;?><option value="<?=e($definition['target_code'])?>" <?=((string)($plot['standings_stat_code']??'')===(string)$definition['target_code'])?'selected':''?>><?=e($definition['label_text'])?> (<?=e($definition['target_code'])?>)</option><?php endforeach;?></select><?=writer_hint('Optional. When set, the play screen shows every character current value for this stat to all players — a public scoreboard.')?></label><label class="field">Standings Title<input name="standings_title" value="<?=e((string)($plot['standings_title']??''))?>" placeholder="e.g. Belindas Tally"><?=writer_hint('Heading for the public standings card — for example, the name of the character keeping score.')?></label><label class="field wide">Scenario Briefing <span class="badge">Required</span><textarea name="scenario_text" rows="8" required><?=e($plot['scenario_text'])?>
</textarea><?=writer_hint('Shared information every player receives before private character knowledge.')?></label><button class="btn">Save Overview</button></form><section class="danger-zone"><h3>Delete Story</h3><?php if($storyUsage):?><p class="help">This story cannot be deleted while it has linked records or play history.</p><p class="code-lock">Locked · <?php $storyParts=[];foreach($storyUsage as$keyword=>$count)$storyParts[]=e($keyword).' '.(int)$count;echo implode(' · ',$storyParts);?></p><?php else:?><p class="help">This permanently deletes the empty story. A story becomes undeletable after content is added or it has been played.</p><form method="post" data-confirm="Permanently delete this empty story?"><?=writer_form_context($plotId,$tab,'delete_story')?><button class="btn alt danger">Delete Story</button></form><?php endif;?></section></div>
