dforeach;?></select></label><label class="field">Value Type<select name="value_type"><option value="PRESET">Preset Values</option><option value="NUMERIC">Numerical</option><option value="TEXT">Free Text</option></select></label><label class="field">Label<input name="label_text" required></label><label class="field" data-definition-field="NUMERIC">Default Numerical Value<input type="number" name="default_numeric_value"></label><label class="field" data-definition-field="PRESET">Allowed Preset Values<textarea name="allowed_values_text" rows="3" placeholder="One value per line"></textarea></label><label class="field">Initial Value<input name="default_text_value"><?=writer_hint('Preset / Free Text only — the state every run starts in, before any effect changes it. For presets it must be one of the allowed values. Blank means no starting state.')?></label><label class="field wide">Writer Guidance<input name="description"></label><label class="field">Display Order<input type="number" name="sort_order" value="100"></label><input type="hidden" name="active" value="1"><button class="btn">Add Story Value</button></form></details><?php endif;?>

