guideForm.addEventListener('submit',async event=>{event.preventDefault();const answer=guideForm.elements.answer.value.trim();if(answer.length<3){setGuideStatus('Give Inky a little more to work with.',true);return;}guideSubmit.disabled=true;guideAnswers[guideStepNumber]=answer;setGuideStatus('Inky is thinking about the next question…');try{const data=await guidePost({genre_id:guideForm.elements.genre_id.value,step:guideStepNumber,answer,answers:JSON.stringify(guideAnswers)});guideLastReply=data.reply||'';renderGuideHistory();if(data.complete){guideBrief=data.brief;guideForm.hidden=true;renderGuideBrief(guideBrief);setGuideStatus('');}else{guideStepNumber=data.next_step;guideStep.textContent='Step '+(guideStepNumber+1)+' of 5';guideQuestion.textContent=data.question;guideForm.elements.answer.value='';guideForm.elements.answer.focus();setGuideStatus('');guideSubmit.disabled=false;}}catch(error){setGuideStatus(error.message||'Inky could not continue the conversation.',true);guideSubmit.disabled=false;}});
guideForm.querySelectorAll('[data-inky-guide-reset]').forEach(button=>button.addEventListener('click',resetGuide));guideComplete?.querySelector('[data-inky-guide-reset]')?.addEventListener('click',resetGuide);
guideComplete?.querySelector('[data-inky-guide-use]')?.addEventListener('click',()=>{if(!guideBrief)return;const newTab=document.querySelector('[data-story-creation-tab="new"]'),newForm=document.querySelector('#story-creation-new form');newForm?.elements.genre_id&&(newForm.elements.genre_id.value=guideForm.elements.genre_id.value);newForm?.elements.title&&(newForm.elements.title.value=guideBrief.title);newForm?.elements.setting_name&&(newForm.elements.setting_name.value=guideBrief.setting_name);newForm?.elements.scenario_text&&(newForm.elements.scenario_text.value=guideBrief.scenario_text);newTab?.click();newForm?.elements.title?.focus();});
}
</script><script>
const inkyDecisionHash=location.hash.match(/^#decision-(\d+)-options$/);if(inkyDecisionHash){const target=document.getElementById('decision-'+inkyDecisionHash[1]+'-options');if(target){target.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}}
</script><script src="assets/toinky-writer-navigation.js?v=<?=filemtime(__DIR__.'/assets/toinky-writer-navigation.js')?>"></script><?php $activeCharacters=array_values(array_filter($w['characters'],static fn($row)=>(int)($row['active']??1)===1));$playerCharacters=count(array_filter($activeCharacters,static fn($row)=>(string)($row['role_type']??'')==='PLAYER'));$npcCharacters=count(array_filter($activeCharacters,static fn($row)=>(string)($row['role_type']??'')==='NPC'));$hasActiveLocation=(bool)count(array_filter($w['locations'],static fn($row)=>(int)($row['active']??1)===1));$characterCapacity=$hasActiveLocation&&($playerCharacters<(int)($plot['max_players']??0)||$npcCharacters<(int)($plot['max_npcs']??0));$characterOptions=array_values(array_map(static fn($row)=>['role_code'=>(string)($row['role_code']??''),'name'=>(string)($row['name']??'')],$activeCharacters));$inkyPrerequisites=['plot'=>$plotId>0,'characters'=>(bool)$activeCharacters,'character_capacity'=>$characterCapacity,'character_options'=>$characterOptions,'values'=>(bool)count(array_filter($w['state_definitions'],static fn($row)=>(int)($row['active']??1)===1)),'opportunities'=>(bool)count(array_filter($w['opportunities'],static fn($row)=>(int)($row['active']??1)===1))];require_once __DIR__.'/_inky.php';render_inky($writer,['context'=>'story-writer','plot_id'=>$plotId,'genres'=>$genres,'plot'=>$plot,'story_values'=>$w['state_definitions'],'inky_prerequisites'=>$inkyPrerequisites]);?></main></div></body></html>
